          "type": "object",
          "additionalProperties": false,
          "required": ["maximum_slides", "stable_media_dimensions", "responsive_images"],
          "properties": {
            "maximum_slides": { "type": "integer", "minimum": 1, "maximum": 12 },
            "stable_media_dimensions": { "const": true },
            "responsive_images": { "const": true }
          }
        }
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://madewiththesehands.local/schemas/component.schema.json",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "collection",
    "label",
    "description",
    "status",
    "version",
    "renderer",
    "variants",
    "spacingModes",
    "slots",
    "fields",
    "accessibility",
    "limits",
    "directusFields"
  ],
  "properties": {
    "collection": { "type": "string", "pattern": "^block_[a-z0-9_]+$" },
    "label": { "type": "string", "minLength": 1 },
    "description": { "type": "string", "minLength": 1 },
    "status": { "enum": ["proposed", "testing", "approved", "deprecated"] },
    "version": { "type": "string", "pattern": "^[0-9]+\\.[0-9]+\\.[0-9]+$" },
    "renderer": { "type": "string", "pattern": "^[A-Z][A-Za-z0-9]+Block$" },
    "primitives": {
      "type": "array",
      "uniqueItems": true,
      "items": { "type": "string", "pattern": "^shadcn:[a-z0-9-]+$" }
    },
    "trustedOpenSource": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "object",
        "additionalProperties": false,
