import fs from 'node:fs/promises';
import Ajv2020 from 'ajv/dist/2020.js';
import {
  APPROVED_COMPONENT_COLLECTIONS,
  COMPONENTS,
  COMPONENT_MANIFEST_VERSION,
} from '../component-system/components.mjs';
import { activePalette, brandFromRecords } from '../lib/brand-settings.mjs';

const root = new URL('../', import.meta.url);
const schema = JSON.parse(await fs.readFile(new URL('component-system/schemas/component.schema.json', root), 'utf8'));
const validate = new Ajv2020({ allErrors: true }).compile(schema);
const errors = [];

for (const component of COMPONENTS) {
  if (!validate(component)) errors.push(`${component.collection}: ${JSON.stringify(validate.errors)}`);
  const directusFieldNames = component.directusFields.map(({ name }) => name);
  if (new Set(directusFieldNames).size !== directusFieldNames.length) {
    errors.push(`${component.collection} has duplicate Directus field contracts.`);
  }
  const spacingField = component.directusFields.find(({ name }) => name === 'spacing');
  if (JSON.stringify(component.spacingModes) !== JSON.stringify(['compact', 'standard', 'generous'])) {
    errors.push(`${component.collection} must use the approved spacing modes.`);
  }
  if (spacingField?.type !== 'string' || spacingField.default !== 'standard') {
    errors.push(`${component.collection}.spacing must be a standard-defaulting string choice.`);
  }
  if (JSON.stringify(spacingField?.choices?.map(([, value]) => value)) !== JSON.stringify(component.spacingModes)) {
    errors.push(`${component.collection}.spacing choices differ from the brand contract.`);
  }
  for (const field of component.directusFields) {
    if (/(?:^|_)(?:css|style|padding|margin|gap|inset)(?:$|_)/i.test(field.name)) {
      errors.push(`${component.collection}.${field.name} bypasses approved presentation tokens.`);
    }
  }
}

const collections = COMPONENTS.map(({ collection }) => collection);
if (new Set(collections).size !== collections.length) errors.push('Component collection names must be unique.');

const renderers = COMPONENTS.map(({ renderer }) => renderer);
if (new Set(renderers).size !== renderers.length) errors.push('Renderer keys must be unique.');

const dispatcher = await fs.readFile(new URL('app/directus-blocks.jsx', root), 'utf8');
for (const collection of APPROVED_COMPONENT_COLLECTIONS) {
  if (!dispatcher.includes(`${collection}:`)) errors.push(`${collection} is missing from the compile-time renderer allowlist.`);
}

for (const requiredConsumer of [
  'lib/directus.js',
  'scripts/bootstrap-directus-mwth.mjs',
  'scripts/create-directus-mcp-user.mjs',
  'scripts/create-directus-site-token.mjs',
]) {
  const source = await fs.readFile(new URL(requiredConsumer, root), 'utf8');
  if (!source.includes('APPROVED_COMPONENT_COLLECTIONS')) {
    errors.push(`${requiredConsumer} does not consume the central component manifest.`);
  }
}

const slideshowSource = await fs.readFile(new URL('app/slideshow-block.jsx', root), 'utf8');
const slideshowLogicSource = await fs.readFile(new URL('lib/slideshow.mjs', root), 'utf8');
const directusPageStyles = await fs.readFile(new URL('app/directus-page.module.css', root), 'utf8');
const shadcnCarouselSource = await fs.readFile(new URL('components/ui/carousel.jsx', root), 'utf8');
const brandBookSource = await fs.readFile(new URL('app/brand/page.jsx', root), 'utf8');
const slideshowContract = COMPONENTS.find(({ collection }) => collection === 'block_slideshow');
for (const primitive of ['shadcn:carousel', 'shadcn:button']) {
  if (!slideshowContract?.primitives?.includes(primitive)) errors.push(`Slideshow must prefer ${primitive}.`);
}
for (const invariant of [
  "prefers-reduced-motion: reduce",
  "aria-label=\"Previous slide\"",
  "aria-label=\"Next slide\"",
  'shouldRunSlideshowAutoplay',
  'wrappedSlideIndex',
  "from '@/components/ui/button'",
  "from '@/components/ui/carousel'",
]) {
  if (!slideshowSource.includes(invariant)) errors.push(`Slideshow invariant missing: ${invariant}`);
}
for (const invariant of [
  'export const MAX_SLIDES = 12',
  'export const MINIMUM_AUTOPLAY_INTERVAL_MS = 4000',
  'value.slice(0, MAX_SLIDES)',
  'autoplay && !paused && !reducedMotion && slideCount > 1',
]) {
  if (!slideshowLogicSource.includes(invariant)) errors.push(`Slideshow logic invariant missing: ${invariant}`);
}
if (!shadcnCarouselSource.includes('aria-roledescription="carousel"')) {
  errors.push('The shadcn Carousel primitive is missing its carousel role.');
}
if (!brandBookSource.includes('<DirectusBlock')) {
  errors.push('The Brand Book is missing compile-time renderer previews.');
}
for (const collection of APPROVED_COMPONENT_COLLECTIONS) {
  if (!brandBookSource.includes(`collection: '${collection}'`)) {
    errors.push(`The Brand Book is missing a live ${collection} renderer preview.`);
  }
}

const slideshowStyleStart = directusPageStyles.indexOf('.slideshowBlock');
const slideshowStyleEnd = directusPageStyles.indexOf(".slot[data-slot='related-content']", slideshowStyleStart);
const slideshowStyles = directusPageStyles.slice(slideshowStyleStart, slideshowStyleEnd);
if (slideshowStyleStart < 0 || slideshowStyleEnd < 0) errors.push('Slideshow styles are not isolated for validation.');
if (/#[0-9a-fA-F]{3,8}\b/.test(slideshowStyles)) {
  errors.push('Slideshow styles contain a raw colour instead of an approved brand token.');
}

const brand = brandFromRecords();
const approvedCssVariables = new Set([
  ...Object.keys(activePalette(brand).tokens).map((token) => `--${token.replaceAll('_', '-')}`),
  ...Object.keys(brand.component_contract.spacing.scale_px).map((token) => `--${token.replaceAll('_', '-')}`),
  '--serif',
  '--sans',
  '--mono',
  '--component-inline',
  '--component-block',
  '--component-gap',
]);
for (const [, variable] of slideshowStyles.matchAll(/var\((--[a-z0-9-]+)\)/g)) {
  if (!approvedCssVariables.has(variable)) errors.push(`Slideshow uses unapproved CSS token ${variable}.`);
}
for (const [, ratio] of slideshowStyles.matchAll(/aspect-ratio:\s*([0-9]+\s*\/\s*[0-9]+)/g)) {
  if (!brand.component_contract.image_ratios.includes(ratio)) {
    errors.push(`Slideshow uses unapproved image ratio ${ratio}.`);
  }
}

if (errors.length) {
  console.error(errors.join('\n'));
  process.exit(1);
}

console.log(`Component manifest ${COMPONENT_MANIFEST_VERSION} is valid (${COMPONENTS.length} components).`);

import assert from 'node:assert/strict';
import {
  APPROVED_COMPONENTS,
  COMPONENT_MANIFEST_VERSION,
} from '../component-system/components.mjs';

const directusUrl = process.env.DIRECTUS_URL || 'http://127.0.0.1:8055';
const token = process.env.DIRECTUS_COMPONENT_FACTORY_TOKEN
  || process.env.DIRECTUS_MCP_TOKEN
  || process.env.DIRECTUS_ADMIN_TOKEN;

if (!token) {
  console.error('A restricted Directus component-factory or MCP token is required for live validation.');
  process.exit(1);
}

async function request(pathname) {
  const response = await fetch(`${directusUrl}${pathname}`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  const body = await response.json().catch(() => null);
  if (!response.ok) {
    const message = body?.errors?.[0]?.message || response.statusText;
    throw new Error(`GET ${pathname}: ${message}`);
  }
  return body?.data;
}

function stable(value) {
  if (Array.isArray(value)) return value.map(stable);
  if (!value || typeof value !== 'object') return value;
  return Object.fromEntries(Object.entries(value).sort(([left], [right]) => left.localeCompare(right))
    .map(([key, entry]) => [key, stable(entry)]));
}

function jsonValue(value, fallback) {
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value !== 'string') return value;
  try {
    return JSON.parse(value);
  } catch {
    return fallback;
  }
}

function assertContractEqual(actual, expected, label) {
  assert.deepEqual(stable(jsonValue(actual, actual)), stable(expected), `${label} differs from the compile-time manifest`);
}

function assertDirectusFieldType(actual, expected, label) {
  if (expected.type === 'uuid' && actual?.type === 'string' && actual?.meta?.interface === 'file-image') return;
  assert.equal(actual?.type, expected.type, `${label} has the wrong Directus type`);
}

const collections = await request('/collections?limit=-1');
const collectionNames = new Set(collections.map(({ collection }) => collection));
const deployedComponents = APPROVED_COMPONENTS.filter(({ collection }) => collectionNames.has(collection));
const pendingComponents = APPROVED_COMPONENTS.filter(({ collection }) => !collectionNames.has(collection));
const sectionFields = await request('/fields/site_sections');
const genericStorageEnabled = ['component_key', 'schema_version', 'data'].every((required) => (
  sectionFields.some(({ field }) => field === required)
));
for (const collection of [
  'component_registry',
  'component_proposals',
  'site_pages',
  'site_pages_blocks',
]) {
  assert.ok(collectionNames.has(collection), `Missing Directus collection: ${collection}`);
}

const commonBlockFields = ['tenant', 'status', 'key', 'eyebrow', 'title', 'dek', 'theme'];
for (const component of deployedComponents) {
  const fields = await request(`/fields/${component.collection}`);
  const fieldsByName = new Map(fields.map((field) => [field.field, field]));
  for (const field of [...commonBlockFields, ...component.directusFields.map(({ name }) => name)]) {
    assert.ok(fieldsByName.has(field), `${component.collection}.${field} is missing in Directus`);
  }
  for (const expected of component.directusFields) {
    assertDirectusFieldType(fieldsByName.get(expected.name), expected, `${component.collection}.${expected.name}`);
  }
}

const registryQuery = new URLSearchParams({
  fields: [
    'key',
    'label',
    'description',
    'block_collection',
    'status',
    'version',
    'variants',
    'allowed_slots',
    'field_contract',
    'accessibility_contract',
    'limits',
    'trusted_open_source',
    'preview_url',
    'renderer_key',
  ].join(','),
  limit: '-1',
});
const registry = await request(`/items/component_registry?${registryQuery}`);
const registryByKey = new Map(registry.map((record) => [record.key, record]));

for (const component of deployedComponents) {
  const record = registryByKey.get(component.collection);
  assert.ok(record, `Missing component_registry record: ${component.collection}`);
  assert.equal(record.status, 'approved', `${component.collection} is not approved in Directus`);
  assert.equal(record.block_collection, genericStorageEnabled ? 'site_sections' : component.collection);
  assert.equal(record.renderer_key, component.renderer);
  assert.equal(record.version, component.version);
  assert.equal(record.preview_url, `/brand#component-${component.collection}`);
  assertContractEqual(record.variants, component.variants, `${component.collection}.variants`);
  assertContractEqual(record.allowed_slots, component.slots, `${component.collection}.allowed_slots`);
  assertContractEqual(record.field_contract, component.directusFields, `${component.collection}.field_contract`);
  assertContractEqual(
    record.accessibility_contract,
    component.accessibility,
    `${component.collection}.accessibility_contract`,
  );
  assertContractEqual(record.limits, component.limits, `${component.collection}.limits`);
  assertContractEqual(record.trusted_open_source || [], component.trustedOpenSource || [], `${component.collection}.trusted_open_source`);
}

if (pendingComponents.length) {
  const proposalQuery = new URLSearchParams({
    fields: 'component_key,status',
    limit: '-1',
  });
  const proposals = await request(`/items/component_proposals?${proposalQuery}`);
  const proposalByKey = new Map(proposals.map((proposal) => [proposal.component_key, proposal]));
  for (const component of pendingComponents) {
    const proposal = proposalByKey.get(component.collection);
    assert.ok(proposal, `${component.collection} is neither deployed nor represented by a governed proposal`);
    assert.notEqual(proposal.status, 'published', `${component.collection} is marked published without a Directus collection`);
  }
}

const relations = await request('/relations/site_pages_blocks');
const pageBuilderRelation = relations.find(({ collection, field }) => (
